window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-8bf9aa608e84df9c"]={"versions": [{"id": "FIG-8bf9aa608e84df9c", "releases": ["R17-10_R1.2.0", "R18-03_R1.4.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur- und Test-Setup-Diagramm für Systemtests des Execution Management in der AUTOSAR Adaptive Platform. Das Diagramm visualisiert die Systemtestumgebung bestehend aus einem Prüfling-Steuergerät (ECU2) und einem CI/CD-basierten Testsystem (Jenkins) samt Schichtenarchitektur von Hardware über Betriebssystem bis zur Anwendungsebene und deren Test-Interaktionen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Setup gliedert sich in zwei Hauptsysteme:</p>\n<ol class=\"fig-list\"><li><strong>ECU2 (Testziel / Target)</strong>:\n<ul class=\"fig-list\"><li><strong>Hardware</strong>: Renesas R-CAR H3 ULCB (unterste Schicht).\n</li><li><strong>Betriebssystem</strong>: Linux with Real-time Patches.\n</li><li><strong>Plattform-Bibliotheken</strong>: POSIX libs (libc, ...).\n</li><li><strong>Plattform-Dienst</strong>: Execution Manager (über POSIX libs).\n</li><li><strong>Laufzeitumgebung</strong>: ARA (AUTOSAR Runtime for Adaptive Applications).\n</li><li><strong>Anwendungen / Clients</strong>: Machine State Client (blau hinterlegt) und System Test Applications (weiß hinterlegter Kasten).\n</li></ul>\n</li><li><strong>Jenkins (Host / Test-Controller)</strong>:\n<ul class=\"fig-list\"><li><strong>Hardware</strong>: PC.\n</li><li><strong>Betriebssystem</strong>: Linux with Real-time Patches.\n</li><li><strong>Framework</strong>: Jenkins (blau hinterlegter Block).\n</li><li><strong>Test-Komponente</strong>: Exec Tester (weiß hinterlegter Kasten).\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Pfade</strong>:\n<ul class=\"fig-list\"><li>Lokaler Stack-Pfad: ARA greift über Pfeilverbindungen auf den Execution Manager zu, dieser nutzt POSIX libs (libc, ...).\n</li><li>Rechnerübergreifende Testpfade: Rot gestrichelte Pfeile führen vom Jenkins-Block bzw. PC über Netzwerk- oder Debug-Kanäle zu den ECU2-Komponenten (Machine State Client und System Test Applications), von wo aus wiederum Rückmeldungen zum Exec Tester geführt werden.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Test-Setup bildet eine automatisierte Testschleife ab:</p>\n<ol class=\"fig-list\"><li>Jenkins bzw. der Exec Tester steuert Systemtests auf dem Zielsystem (ECU2) an.\n</li><li>Signalisierung und Befehle laufen über die gestrichelten Kommunikationslinien zur ECU2 und adressieren dort den Machine State Client sowie die System Test Applications.\n</li><li>Der Machine State Client interagiert über die ARA-Schnittstellen mit dem Execution Manager, um Zustandsübergänge der Maschine auszulösen.\n</li><li>Der Execution Manager agiert auf Betriebssystem- und Bibliotheksebene über POSIX-Aufrufe, um Prozesse und Applikationen zu steuern und zu überwachen.\n</li><li>Die System Test Applications melden Ergebnisse und Status zurück an den Exec Tester auf der Jenkins-Instanz.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Technischer Bericht (TR) zur Illustration des Testaufbaus für funktionale Systemtests des Execution Management. Zeigt Entwicklern und Testingenieuren die Verteilung der Testartefakte, die notwendige Entkopplung zwischen CI-Controller (Jenkins) und Ziel-Hardware (R-CAR H3 ULCB) sowie die Einbindung der funktionalen Schnittstellen (Machine State Client, ARA, Execution Management) im Testbetrieb.</p>"}, {"id": "FIG-c6a762b19bf2eeb6", "releases": ["R18-10-1", "R18-10_R4.4.0_R1.5.0", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur- und Test-Setup-Diagramm für Systemtests des Execution Management in der AUTOSAR Adaptive Platform. Das Diagramm visualisiert die Systemtestumgebung bestehend aus einem Prüfling-Steuergerät (ECU2) und einem CI/CD-basierten Testsystem (Jenkins) samt Schichtenarchitektur von Hardware über Betriebssystem bis zur Anwendungsebene und deren Test-Interaktionen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Setup gliedert sich in zwei Hauptsysteme:</p>\n<ol class=\"fig-list\"><li><strong>ECU2 (Testziel / Target)</strong>:\n<ul class=\"fig-list\"><li><strong>Hardware</strong>: Renesas R-CAR H3 ULCB (unterste Schicht).\n</li><li><strong>Betriebssystem</strong>: Linux with Real-time Patches.\n</li><li><strong>Plattform-Bibliotheken</strong>: POXIS libs (libc, ...).\n</li><li><strong>Plattform-Dienst</strong>: Execution Manager (über POXIS libs).\n</li><li><strong>Laufzeitumgebung</strong>: ARA (AUTOSAR Runtime for Adaptive Applications).\n</li><li><strong>Anwendungen / Clients</strong>: Machine State Client (blau hinterlegt) und System Test Applications (weiß hinterlegter Kasten).\n</li></ul>\n</li><li><strong>Jenkins (Host / Test-Controller)</strong>:\n<ul class=\"fig-list\"><li><strong>Hardware</strong>: PC.\n</li><li><strong>Betriebssystem</strong>: Linux (Standard-Linux ohne Echtzeit-Erweiterung).\n</li><li><strong>Framework</strong>: Jenkins (großer, vertikal gestreckter Block).\n</li><li><strong>Test-Komponente</strong>: Exec Tester (weiß hinterlegter Kasten).\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Pfade</strong>:\n<ul class=\"fig-list\"><li>Lokaler Stack-Pfad: Zwei Pfeilspitzen weisen von ARA nach unten auf den Execution Manager; zwei Pfeilspitzen weisen vom Execution Manager nach unten auf POXIS libs (libc, ...). Zudem führen Pfeile von ARA nach oben zu Machine State Client und System Test Applications.\n</li><li>Rechnerübergreifende Testpfade: Rot gestrichelte Verbindungslinien verbinden den Jenkins-Host mit der Zielhardware und den Testapplikationen (Machine State Client, System Test Applications) sowie dem Exec Tester.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Test-Setup bildet eine automatisierte Testschleife ab:</p>\n<ol class=\"fig-list\"><li>Jenkins bzw. der Exec Tester steuert Systemtests auf dem Zielsystem (ECU2) an.\n</li><li>Signalisierung und Befehle laufen über die gestrichelten Kommunikationslinien zur ECU2 und adressieren dort den Machine State Client sowie die System Test Applications.\n</li><li>Der Machine State Client interagiert über die ARA-Schnittstellen mit dem Execution Manager, um Zustandsübergänge der Maschine auszulösen.\n</li><li>Der Execution Manager agiert auf Betriebssystem- und Bibliotheksebene über POSIX-Aufrufe, um Prozesse und Applikationen zu steuern und zu überwachen.\n</li><li>Die System Test Applications melden Ergebnisse und Status zurück an den Exec Tester auf der Jenkins-Instanz.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Technischer Bericht (TR) zur Illustration des Testaufbaus für funktionale Systemtests des Execution Management. Zeigt Entwicklern und Testingenieuren die Verteilung der Testartefakte, die notwendige Entkopplung zwischen CI-Controller (Jenkins) und Ziel-Hardware (R-CAR H3 ULCB) sowie die Einbindung der funktionalen Schnittstellen (Machine State Client, ARA, Execution Management) im Testbetrieb.</p>"}, {"id": "FIG-703cee964fceeca8", "releases": ["R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur- und Test-Setup-Diagramm für Systemtests des Execution Management in der AUTOSAR Adaptive Platform. Das Diagramm visualisiert die Systemtestumgebung bestehend aus einem Prüfling-Steuergerät (ECU2) und einem CI/CD-basierten Testsystem (Jenkins) samt Schichtenarchitektur von Hardware über Betriebssystem bis zur Anwendungsebene und deren Test-Interaktionen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Setup gliedert sich in zwei Hauptsysteme:</p>\n<ol class=\"fig-list\"><li><strong>ECU2 (Testziel / Target)</strong>:\n<ul class=\"fig-list\"><li><strong>Hardware</strong>: Renesas R-CAR H3 ULCB (unterste Schicht).\n</li><li><strong>Betriebssystem</strong>: Linux with Real-time Patches.\n</li><li><strong>Plattform-Bibliotheken</strong>: POSIX libs (libc, ...).\n</li><li><strong>Plattform-Dienst</strong>: Execution Manager (über POSIX libs).\n</li><li><strong>Laufzeitumgebung</strong>: ARA (AUTOSAR Runtime for Adaptive Applications).\n</li><li><strong>Anwendungen / Clients</strong>: Machine State Client (blau hinterlegt) und EMO Test Application(s) (weiß hinterlegter Kasten).\n</li></ul>\n</li><li><strong>Jenkins (Host / Test-Controller)</strong>:\n<ul class=\"fig-list\"><li><strong>Hardware</strong>: PC.\n</li><li><strong>Betriebssystem</strong>: Linux.\n</li><li><strong>Framework</strong>: Jenkins (blau hinterlegter Block).\n</li><li><strong>Test-Komponente</strong>: EMO Tester (weiß hinterlegter Kasten).\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Pfade</strong>:\n<ul class=\"fig-list\"><li>Lokaler Stack-Pfad: Zwei Pfeilspitzen weisen von ARA nach unten auf den Execution Manager; zwei Pfeilspitzen weisen vom Execution Manager nach unten auf POSIX libs (libc, ...). Zudem führen Pfeile von ARA nach oben zu Machine State Client und EMO Test Application(s).\n</li><li>Rechnerübergreifende Testpfade: Rot gestrichelte Pfeillinien verbinden den Jenkins-Host über die Hardware-Ebene mit dem Machine State Client und den EMO Test Application(s) sowie zurück zum EMO Tester.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Test-Setup bildet eine automatisierte Testschleife ab:</p>\n<ol class=\"fig-list\"><li>Jenkins bzw. der EMO Tester steuert Systemtests auf dem Zielsystem (ECU2) an.\n</li><li>Signalisierung und Befehle laufen über die gestrichelten Kommunikationslinien zur ECU2 und adressieren dort den Machine State Client sowie die EMO Test Application(s).\n</li><li>Der Machine State Client interagiert über die ARA-Schnittstellen mit dem Execution Manager, um Zustandsübergänge der Maschine auszulösen.\n</li><li>Der Execution Manager agiert auf Betriebssystem- und Bibliotheksebene über POSIX-Aufrufe, um Prozesse und Applikationen zu steuern und zu überwachen.\n</li><li>Die EMO Test Application(s) melden Ergebnisse und Status zurück an den EMO Tester auf der Jenkins-Instanz.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Technischer Bericht (TR) zur Illustration des Testaufbaus für funktionale Systemtests des Execution Management. Zeigt Entwicklern und Testingenieuren die Verteilung der Testartefakte, die notwendige Entkopplung zwischen CI-Controller (Jenkins) und Ziel-Hardware (R-CAR H3 ULCB) sowie die Einbindung der funktionalen Schnittstellen (Machine State Client, ARA, Execution Management) im Testbetrieb.</p>"}], "trans": [{"from": "FIG-8bf9aa608e84df9c", "to": "FIG-c6a762b19bf2eeb6", "fr": "R18-03_R1.4.0", "tr": "R18-10-1", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li><strong>Jenkins-Betriebssystemschicht</strong>: Beschriftung von „Linux with Real-time Patches“ zu „Linux“ geändert.\n</li><li><strong>Bibliotheksschicht (ECU2)</strong>: Tippfehler in der Beschriftung korrigiert von „POSIX libs (libc, ...)“ zu „POXIS libs (libc, ...)“.\n</li><li><strong>Pfeilverbindungen</strong>: Der Pfeil zwischen „ARA“ und „Execution Manager“ wurde von einer einzelnen Pfeilspitze auf zwei Pfeilspitzen aufgeteilt; der Pfeil von „Execution Manager“ zu den POSIX-Bibliotheken wurde ebenfalls verdoppelt (zwei parallele Pfeilspitzen nach unten).\n</li><li><strong>Layout</strong>: Gestreckte vertikale Anordnung der Komponentenblöcke.\n</li></ul>"}, {"from": "FIG-c6a762b19bf2eeb6", "to": "FIG-703cee964fceeca8", "fr": "R19-03", "tr": "R19-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li><strong>Testapplikation (ECU2)</strong>: Beschriftung von „System Test Applications“ zu „EMO Test Application(s)“ geändert.\n</li><li><strong>Test-Komponente (Jenkins)</strong>: Beschriftung von „Exec Tester“ zu „EMO Tester“ geändert.\n</li><li><strong>Bibliotheksschicht (ECU2)</strong>: Tippfehler behoben und zurückkorrigiert von „POXIS libs (libc, ...)“ zu „POSIX libs (libc, ...)“.\n</li></ul>"}]};
